namespace CreditMonitor.Insights {
 // System SQLite on supported Windows. All user values are bound parameters.
 public sealed partial class HistoryStore : IDisposable {
  readonly object gate=new object();readonly string filePath;IntPtr db;
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_open_v2(byte[] file,out IntPtr db,int flags,IntPtr vfs);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_close_v2(IntPtr db);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_busy_timeout(IntPtr db,int ms);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_prepare_v2(IntPtr db,byte[] sql,int size,out IntPtr stmt,IntPtr tail);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_bind_text(IntPtr stmt,int index,byte[] value,int size,IntPtr destroy);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_bind_int64(IntPtr stmt,int index,long value);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_bind_double(IntPtr stmt,int index,double value);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_bind_null(IntPtr stmt,int index);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_step(IntPtr stmt);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_finalize(IntPtr stmt);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_column_count(IntPtr stmt);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern IntPtr sqlite3_column_name(IntPtr stmt,int i);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_column_type(IntPtr stmt,int i);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern long sqlite3_column_int64(IntPtr stmt,int i);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern double sqlite3_column_double(IntPtr stmt,int i);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern IntPtr sqlite3_column_text(IntPtr stmt,int i);
  [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_column_bytes(IntPtr stmt,int i);
  static byte[] Utf8(string v){return Encoding.UTF8.GetBytes(v+"\0");}
  static string Text(IntPtr p,int len){if(p==IntPtr.Zero)return null;byte[] b=new byte[len];Marshal.Copy(p,b,0,len);return Encoding.UTF8.GetString(b);}
  public HistoryStore(string path,bool readOnly=false){filePath=Path.GetFullPath(path);Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path)));if(sqlite3_open_v2(Utf8(path),out db,(readOnly?1:6)|0x10000,IntPtr.Zero)!=0){Dispose();throw new IOException("Cannot open local history");}try{sqlite3_busy_timeout(db,3000);if(readOnly)return;Run("PRAGMA journal_mode=WAL");Run("PRAGMA synchronous=FULL");Run("PRAGMA recursive_triggers=ON");var version=Query("PRAGMA user_version");if(Convert.ToInt32(version[0]["user_version"])>2)throw new IOException("History schema is newer than this app; use the newer app");Run("CREATE TABLE IF NOT EXISTS events(k TEXT PRIMARY KEY,tool TEXT,provider TEXT,account TEXT,device TEXT,model TEXT,project TEXT,session TEXT,at TEXT,i INTEGER,o INTEGER,c INTEGER,w INTEGER,r INTEGER)");Run("DROP INDEX IF EXISTS events_time");Run("CREATE TABLE IF NOT EXISTS quotas(provider TEXT,scope TEXT,window TEXT,at TEXT,reset TEXT,remaining REAL,minutes REAL,PRIMARY KEY(provider,scope,window,at))");Run("CREATE INDEX IF NOT EXISTS quota_time ON quotas(at)");Run("CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT)");InitRetention();InitStatistics();Run("PRAGMA user_version=2");}catch{Dispose();throw;}}
  public List<Dictionary<string,object>> Query(string sql,params object[] args){lock(gate){if(db==IntPtr.Zero)throw new ObjectDisposedException("HistoryStore");IntPtr stmt;if(sqlite3_prepare_v2(db,Utf8(sql),-1,out stmt,IntPtr.Zero)!=0)throw new IOException("History query could not be prepared");try{for(int j=0;j<args.Length;j++){object a=args[j];int rc=a==null?sqlite3_bind_null(stmt,j+1):a is double?sqlite3_bind_double(stmt,j+1,(double)a):a is int||a is long?sqlite3_bind_int64(stmt,j+1,Convert.ToInt64(a)):sqlite3_bind_text(stmt,j+1,Utf8(Convert.ToString(a,CultureInfo.InvariantCulture)),Encoding.UTF8.GetByteCount(Convert.ToString(a,CultureInfo.InvariantCulture)),new IntPtr(-1));if(rc!=0)throw new IOException("History parameter rejected");}var rows=new List<Dictionary<string,object>>();int step;while((step=sqlite3_step(stmt))==100){var row=new Dictionary<string,object>();for(int i=0;i<sqlite3_column_count(stmt);i++){string name=Marshal.PtrToStringAnsi(sqlite3_column_name(stmt,i));int type=sqlite3_column_type(stmt,i);row[name]=type==5?null:type==1?(object)sqlite3_column_int64(stmt,i):type==2?(object)sqlite3_column_double(stmt,i):Text(sqlite3_column_text(stmt,i),sqlite3_column_bytes(stmt,i));}rows.Add(row);}if(step!=101)throw new IOException("History write/read failed");return rows;}finally{sqlite3_finalize(stmt);}}}
  void Run(string sql,params object[] args){Query(sql,args);}
  public string Setting(string key,string fallback){var r=Query("SELECT v FROM settings WHERE k=?",key);return r.Count==0?fallback:Convert.ToString(r[0]["v"]);}
  public void Set(string key,string value){Run("INSERT OR REPLACE INTO settings(k,v) VALUES(?,?)",key,value);}
  public void Upsert(UsageEvent e){e.Model=String.IsNullOrWhiteSpace(e.Model)?"unknown":e.Model;e.Project=String.IsNullOrWhiteSpace(e.Project)?"unattributed":e.Project;e.Validate();lock(gate){var receipt=Query("SELECT i,o,c,w,r,payload,model,project FROM retired WHERE k=?",e.Key);if(receipt.Count>0){var n=receipt[0];if(e.Input>(long)n["i"]||e.Output>(long)n["o"]||e.Cached>(long)n["c"]||e.CacheWrite>(long)n["w"]||e.Reasoning>(long)n["r"]||((string)n["model"]=="unknown"&&e.Model!="unknown")||((string)n["project"]=="unattributed"&&e.Project!="unattributed"))CorrectRetired(e,n);return;}var old=Query("SELECT i,o,c,w,r,model,project FROM events WHERE k=?",e.Key);long input=e.Input,output=e.Output,cache=e.Cached,write=e.CacheWrite,reason=e.Reasoning;if(old.Count>0){if((string)old[0]["model"]!="unknown")e.Model=(string)old[0]["model"];if((string)old[0]["project"]!="unattributed")e.Project=(string)old[0]["project"];input=Math.Max(input,Convert.ToInt64(old[0]["i"]));output=Math.Max(output,Convert.ToInt64(old[0]["o"]));cache=Math.Max(cache,Convert.ToInt64(old[0]["c"]));write=Math.Max(write,Convert.ToInt64(old[0]["w"]));reason=Math.Max(reason,Convert.ToInt64(old[0]["r"]));}input=Math.Max(input,cache+write);output=Math.Max(output,reason);Run("INSERT OR REPLACE INTO events VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",e.Key,e.Tool,e.Provider,e.Account,e.Device,e.Model??"unknown",e.Project??"unattributed",e.Session,InsightIdentity.Time(e.At),input,output,cache,write,reason);}}
  public void Import(IEnumerable<UsageEvent> events){var batch=new List<UsageEvent>();foreach(var e in events){e.Validate();batch.Add(e);if(batch.Count==100){ImportBatch(batch);batch.Clear();}}if(batch.Count>0)ImportBatch(batch);}
  void ImportBatch(List<UsageEvent> batch){lock(gate){Run("BEGIN IMMEDIATE");try{foreach(var e in batch)Upsert(e);Run("COMMIT");}catch{Run("ROLLBACK");throw;}}}
  public void Quota(QuotaSample q){if(String.IsNullOrEmpty(q.Scope)||String.IsNullOrEmpty(q.Provider)||String.IsNullOrEmpty(q.Window)||Double.IsNaN(q.Remaining)||q.Remaining<0||q.Remaining>100||q.At.ToUniversalTime()>DateTime.UtcNow.AddSeconds(5))return;Run("INSERT OR IGNORE INTO quotas VALUES(?,?,?,?,?,?,?)",q.Provider,q.Scope,q.Window,InsightIdentity.Time(q.At),q.ResetAt.HasValue?InsightIdentity.Time(q.ResetAt.Value):null,q.Remaining,q.Minutes.HasValue?(object)q.Minutes.Value:null);}
  static UsageEvent RowEvent(Dictionary<string,object> r){return new UsageEvent{Key=(string)r["k"],Tool=(string)r["tool"],Provider=(string)r["provider"],Account=(string)r["account"],Device=(string)r["device"],Model=(string)r["model"],Project=(string)r["project"],Session=(string)r["session"],At=DateTime.Parse((string)r["at"],CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),Input=(long)r["i"],Output=(long)r["o"],Cached=(long)r["c"],CacheWrite=(long)r["w"],Reasoning=(long)r["r"],Aggregate=r.ContainsKey("granularity")&&(string)r["granularity"]!="event",Granularity=r.ContainsKey("granularity")?(string)r["granularity"]:"event",RequestEvents=r.ContainsKey("requests")?checked((int)(long)r["requests"]):1};}
  public List<UsageEvent> Events(HistoryFilter filter=null){lock(gate){filter=filter??new HistoryFilter{From=new DateTime(2020,1,1),To=DateTime.UtcNow.AddMinutes(1)};var rows=Query("SELECT * FROM events WHERE at>=? AND at<? ORDER BY at",InsightIdentity.Time(filter.From),InsightIdentity.Time(filter.To));var buckets=Query("SELECT * FROM buckets WHERE at>=? AND at<? ORDER BY at",InsightIdentity.Time(filter.From),InsightIdentity.Time(filter.To));return rows.Concat(buckets).Select(RowEvent).Where(filter.Matches).OrderBy(e=>e.At).ToList();}}
  internal HistoryStore OpenSnapshot(){var reader=new HistoryStore(filePath,true);try{reader.Run("BEGIN");reader.Query("SELECT k FROM events LIMIT 1");return reader;}catch{reader.Dispose();throw;}}
  public List<UsageEvent> SnapshotEvents(HistoryFilter filter=null){using(var reader=new HistoryStore(filePath,true)){reader.Run("BEGIN");try{var result=reader.Events(filter);reader.Run("COMMIT");return result;}catch{reader.Run("ROLLBACK");throw;}}}
  public List<QuotaSample> Quotas(int limit=50000){return Query("SELECT * FROM quotas ORDER BY at DESC LIMIT ?",Math.Max(1,Math.Min(50000,limit))).Select(r=>new QuotaSample{Provider=(string)r["provider"],Scope=(string)r["scope"],Window=(string)r["window"],At=DateTime.Parse((string)r["at"],CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),ResetAt=r["reset"]==null?(DateTime?)null:DateTime.Parse((string)r["reset"],CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),Remaining=Convert.ToDouble(r["remaining"]),Minutes=r["minutes"]==null?(double?)null:Convert.ToDouble(r["minutes"])}).ToList();}
  public void Dispose(){lock(gate){if(db!=IntPtr.Zero){sqlite3_close_v2(db);db=IntPtr.Zero;}}}
 }
